const nav=document.querySelector('#nav'),app=document.querySelector('#app');Object.keys(pages).forEach((p,i)=>{let b=document.createElement('button');b.textContent=p;b.onclick=()=>render(p);nav.appendChild(b)});
function render(name){[...nav.children].forEach(b=>b.classList.toggle('active',b.textContent===name));let p=pages[name];app.innerHTML=`<div class="head"><div><h1>${name}</h1><div class="muted">Administration et supervision</div></div><button class="btn">${p.action}</button></div><div class="filters">${p.filters.map((f,i)=>i?`<select><option>${f}</option></select>`:`<input placeholder="${f}">`).join('')}</div><div class="kpis">${p.kpis.map(k=>`<div class="card kpi"><small>${k[0]}</small><strong>${k[1]}</strong></div>`).join('')}</div><div class="grid"><div class="card"><h2>${name==='Journaux'?'Flux de journaux':'Vue principale'}</h2><table><thead><tr>${p.table.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${p.rows.map((r,ri)=>`<tr>${r.map((x,i)=>`<td class="${name==='Journaux'?'log':''}">${i===r.length-1?`<span class="badge ${x.includes('Révo')||x.includes('Dégrad')?'warn':''}">${x}</span>`:x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="card"><h2>${name==='Observabilité'?'Santé des services':'Activité'}</h2><div class="chart">${[36,72,48,89,64,96,58,78,51,84,67,92].map(h=>`<div class="bar" style="height:${h}%"></div>`).join('')}</div><div class="side-list"><div>Dernière mise à jour : à l’instant</div><div>État global : opérationnel</div><div class="muted">Les détails sont administratifs.</div></div></div></div>`}
render('Circuits');